function setMeta(selector, value) {
  let element = document.head.querySelector(selector)
  if (!element) {
    element = document.createElement('meta')
    const key = selector.match(/\[([^=]+)=/)?.[1]
    const name = selector.match(/="([^"]+)"/)?.[1]
    if (key && name) element.setAttribute(key, name)
    document.head.appendChild(element)
  }
  element.setAttribute('content', value)
}

function SeoManager() {
  const location = useLocation()
  useEffect(() => {
    const normalizeHomeAnchor = event => {
      const anchor = event.target.closest('a[href^="#"]')
      if (!anchor || location.pathname === '/') return
      const hash = anchor.getAttribute('href')
      if (!hash || hash === '#') return
      event.preventDefault()
      window.location.assign(`/${hash}`)
    }
    document.addEventListener('click', normalizeHomeAnchor)
    return () => document.removeEventListener('click', normalizeHomeAnchor)
  }, [location.pathname])
  useEffect(() => {
    if (location.pathname !== '/' || !location.hash) return
    const targetId = decodeURIComponent(location.hash.slice(1))
    let frame = 0
    const scrollToTarget = () => {
      const target = document.getElementById(targetId)
      if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' })
      else frame = requestAnimationFrame(scrollToTarget)
    }
    frame = requestAnimationFrame(scrollToTarget)
    return () => cancelAnimationFrame(frame)
  }, [location.pathname, location.hash])
  useEffect(() => {
    const path = location.pathname.replace(/\/$/, '') || '/'
    const seo = SEO_ROUTES[path] || SEO_DEFAULTS
    const canonical = `${SITE_URL}${path === '/' ? '/' : path}`
    const image = seo.image.startsWith('http') ? seo.image : `${SITE_URL}${seo.image}`
    document.title = seo.title
    setMeta('meta[name="description"]', seo.description)
    setMeta('meta[property="og:title"]', seo.title)
    setMeta('meta[property="og:description"]', seo.description)
    setMeta('meta[property="og:url"]', canonical)
    setMeta('meta[property="og:image"]', image)
    setMeta('meta[name="twitter:title"]', seo.title)
    setMeta('meta[name="twitter:description"]', seo.description)
    setMeta('meta[name="twitter:image"]', image)
    let link = document.head.querySelector('link[rel="canonical"]')
    if (!link) {
      link = document.createElement('link')
      link.rel = 'canonical'
      document.head.appendChild(link)
    }
    link.href = canonical
  }, [location.pathname])
  return null
}

