function ThemeToggle(){const [theme,setTheme]=useState('light');useEffect(()=>{document.documentElement.dataset.theme=theme;document.documentElement.style.colorScheme=theme;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',theme==='light'?'#f4f4f1':'#161616')},[theme]);const dark=theme==='dark';return <button type="button" onClick={()=>setTheme(dark?'light':'dark')} className="theme-toggle" aria-label={dark?'Aktifkan light mode':'Aktifkan dark mode'} title={dark?'Aktifkan light mode':'Aktifkan dark mode'} aria-pressed={!dark}>{dark?<Sun size={19}/>:<Moon size={19}/>}</button>}
