function GlobalDocumentsPage(){
  const [documents,setDocuments]=useState(null),[error,setError]=useState(''),[downloading,setDownloading]=useState('')
  useEffect(()=>{api('/content/general-documents').then(data=>setDocuments(data.documents||[])).catch(requestError=>{setError(requestError.message);setDocuments([])})},[])
  const downloadDocument=async document=>{setDownloading(document.file_path);setError('');try{const response=await fetch(`${STORAGE}/${document.file_path}`);if(!response.ok)throw new Error('File tidak dapat diunduh.');const blob=await response.blob(),url=URL.createObjectURL(blob),anchor=window.document.createElement('a');anchor.href=url;anchor.download=document.original_name||document.title;window.document.body.appendChild(anchor);anchor.click();anchor.remove();URL.revokeObjectURL(url)}catch(requestError){setError(requestError.message)}finally{setDownloading('')}}
  return <section className="min-h-[70vh] bg-[#f4f4f1] px-5 py-14 lg:px-8"><div className="mx-auto max-w-5xl"><div className="max-w-2xl"><div className="font-mono text-[11px] font-bold uppercase tracking-[.18em] text-blue-600">Dokumen global</div><h1 className="mt-3 font-display text-4xl font-extrabold tracking-tight sm:text-6xl">Download Dokumen</h1><p className="mt-4 text-base leading-7 text-slate-600">Unduh formulir, panduan, dan dokumen umum resmi yang telah diunggah melalui ruang admin BSI Flash.</p></div>{error&&<div className="mt-7 rounded-2xl bg-rose-100 p-4 text-sm font-bold text-rose-700">{error}</div>}{documents===null?<div className="mt-10"><Loader/></div>:documents.length?<div className="mt-10 grid gap-4 sm:grid-cols-2">{documents.map((document,index)=><article key={`${document.file_path}-${index}`} className="flex flex-col rounded-3xl border border-slate-200 bg-white p-5 shadow-sm"><span className="grid size-12 place-items-center rounded-2xl bg-blue-100 text-blue-700"><FileCheck2 size={22}/></span><h2 className="mt-5 font-display text-xl font-bold">{document.title}</h2><p className="mt-2 flex-1 text-sm leading-6 text-slate-500">{document.description||document.original_name}</p><div className="mt-5 border-t border-slate-100 pt-4"><button type="button" onClick={()=>downloadDocument(document)} disabled={downloading===document.file_path} className="btn-primary w-full py-3 disabled:opacity-60"><Download size={17}/>{downloading===document.file_path?'Mengunduh...':'Download File'}</button></div></article>)}</div>:<div className="mt-10"><Empty title="Belum ada dokumen" text="Dokumen akan muncul otomatis setelah diunggah oleh admin."/></div>}</div></section>
}

const HERO_FALLBACK={badge:'Kompetisi pelajar nasional 2027',title_primary:'BSI FLASH 2027',title_accent:'UNLEASH YOUR POTENTIAL',description:'BSI Flash 2027 merupakan rangkaian kompetisi pelajar tingkat nasional yang diselenggarakan secara hybrid, baik daring maupun luring, untuk siswa SLTA dan sederajat dari berbagai daerah di Indonesia. Program ini menjadi ruang bagi generasi muda untuk mengembangkan kreativitas, sportivitas, kemampuan akademik, keterampilan digital, kepemimpinan, kerja sama tim, serta keberanian dalam menunjukkan potensi terbaiknya. Melalui kategori Sport Competition, Talent Competition, dan Science Competition, setiap peserta memperoleh pengalaman berkompetisi yang terarah, bertemu dengan pelajar berbakat lainnya, mendapatkan informasi kegiatan yang transparan, serta memantau seluruh proses pendaftaran melalui satu dashboard. BSI Flash tidak hanya menghadirkan perlombaan, tetapi juga membangun ekosistem pembelajaran yang mendorong lahirnya generasi mandiri, berprestasi, adaptif, dan siap memberikan kontribusi positif untuk masa depan Indonesia yang lebih baik.',primary_button_label:'Temukan Lomba',primary_button_url:'/lomba',secondary_button_label:'Masuk Dashboard',secondary_button_url:'/login',hashtag:'#BSIFLASH2027'}
