function useLandingReveal(){
  const root=useRef(null)
  useEffect(()=>{
    const container=root.current
    if(!container)return
    const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches
    const reveal=element=>element.classList.add('is-visible')
    const register=scope=>{
      const elements=[]
      if(scope.nodeType===1&&scope.matches?.('[data-reveal]'))elements.push(scope)
      scope.querySelectorAll?.('[data-reveal]').forEach(element=>elements.push(element))
      elements.forEach(element=>reduced||!observer?reveal(element):observer.observe(element))
    }
    const observer=reduced||!('IntersectionObserver' in window)?null:new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){reveal(entry.target);observer.unobserve(entry.target)}}),{threshold:.12,rootMargin:'0px 0px -7% 0px'})
    register(container)
    const mutations=new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(register)))
    mutations.observe(container,{childList:true,subtree:true})
    return()=>{mutations.disconnect();observer?.disconnect()}
  },[])
  return root
}

