function HeroParticipant(){
  const {year}=useEdition(),fallback={...HERO_FALLBACK,badge:`Kompetisi pelajar nasional ${year}`,title_primary:`BSI FLASH ${year}`,description:HERO_FALLBACK.description.replaceAll('2027',year),hashtag:`#BSIFLASH${year}`}
  const [content,setContent]=useState(fallback),[competitions,setCompetitions]=useState([]),[activeIndex,setActiveIndex]=useState(0)
  const swipe=useRef({start:null,moved:false})
  useEffect(()=>{api('/content/home-hero').then(setContent).catch(()=>{})},[])
  useEffect(()=>{api('/competitions?status=Buka&active=1').then(items=>{setCompetitions(items.length?items:HOMEPAGE_SHOWCASE_COMPETITIONS);setActiveIndex(0)}).catch(()=>setCompetitions(HOMEPAGE_SHOWCASE_COMPETITIONS))},[])
  const changeSlide=direction=>setActiveIndex(current=>competitions.length?(current+direction+competitions.length)%competitions.length:0)
  const visibleCount=Math.min(7,competitions.length),offsets=SHOWCASE_OFFSETS[visibleCount]||[]
  const fanItems=offsets.map(offset=>({item:competitions[(activeIndex+offset+competitions.length)%competitions.length],offset,style:SHOWCASE_FAN_STYLES[offset+3]}))
  const touchStart=event=>{swipe.current={start:event.touches[0]?.clientX??null,moved:false}}
  const touchMove=event=>{if(swipe.current.start!==null&&Math.abs((event.touches[0]?.clientX||0)-swipe.current.start)>12)swipe.current.moved=true}
  const touchEnd=event=>{const end=event.changedTouches[0]?.clientX??swipe.current.start,delta=end-swipe.current.start;if(Math.abs(delta)>45)changeSlide(delta>0?-1:1);setTimeout(()=>{swipe.current={start:null,moved:false}},0)}
  return <section className="landing-showcase noise overflow-hidden text-white"><div className="open9-hero-grid"/><div className="showcase-spark showcase-spark-one"><Sparkles size={27}/></div><div className="showcase-spark showcase-spark-two"><Sparkles size={38}/></div><div className="showcase-coin showcase-coin-one"><Trophy size={25}/></div><div className="showcase-coin showcase-coin-two"><Zap size={24} fill="currentColor"/></div><div className="showcase-copy relative z-20 mx-auto max-w-3xl px-5 text-center"><div className="open9-kicker justify-center">{content.title_accent||content.badge}</div><h1 className="showcase-title mt-6">{content.title_primary}</h1><p className="mx-auto mt-7 max-w-2xl font-mono text-sm leading-7 text-white/45">{content.description}</p><div className="mt-10 flex flex-wrap justify-center gap-4"><a className="btn-primary min-w-48 px-7" href={content.primary_button_url}>{content.primary_button_label}<ArrowUpRight size={18}/></a><a className="showcase-secondary-btn min-w-48" href={content.secondary_button_url}>{content.secondary_button_label}<ArrowUpRight size={18}/></a></div></div><div className="showcase-slider"><div className="showcase-fan" tabIndex={competitions.length>1?0:undefined} onKeyDown={event=>{if(event.key==='ArrowLeft')changeSlide(-1);if(event.key==='ArrowRight')changeSlide(1)}} onTouchStart={touchStart} onTouchMove={touchMove} onTouchEnd={touchEnd} aria-label="Slider lomba dengan pendaftaran aktif">{fanItems.length?fanItems.map(({item,offset,style})=>{const [x,y,rotate,scale,z]=style;return <Link key={item.id} to={item.slug?`/lomba/${item.slug}`:'/lomba'} onClick={event=>{if(swipe.current.moved)event.preventDefault()}} className={`showcase-fan-card ${offset===0?'is-active':''}`} aria-current={offset===0?'true':undefined} style={{'--fan-x':`${x}px`,'--fan-y':`${y}px`,'--fan-rotate':`${rotate}deg`,'--fan-scale':scale,'--fan-z':z}}><div className="showcase-fan-media"><img src={item.poster_url} alt={item.title}/><span>{item.competition_type?.name||item.category||'Competition'}</span></div><div className="showcase-fan-meta"><h3>{item.title}</h3><div><span>{money(item.fee||0)}</span><ArrowUpRight size={16}/></div></div></Link>}):<div className="showcase-empty-card"><Trophy size={72}/><span>Belum ada lomba dengan pendaftaran aktif</span></div>}</div>{competitions.length>1&&<div className="showcase-slider-controls"><button type="button" onClick={()=>changeSlide(-1)} aria-label="Lomba sebelumnya"><ChevronLeft size={20}/></button><div className="showcase-slider-dots" aria-label={`Lomba ${activeIndex+1} dari ${competitions.length}`}>{competitions.map((item,index)=><button type="button" key={item.id} onClick={()=>setActiveIndex(index)} className={index===activeIndex?'active':''} aria-label={`Tampilkan ${item.title}`} aria-current={index===activeIndex?'true':undefined}/>)}</div><button type="button" onClick={()=>changeSlide(1)} aria-label="Lomba berikutnya"><ChevronRight size={20}/></button></div>}</div></section>
}

