function TestimonialsSection({title,items,interval=6}){
  const [active,setActive]=useState(0),[paused,setPaused]=useState(false)
  useEffect(()=>{if(active>=items.length)setActive(0)},[active,items.length])
  useEffect(()=>{if(items.length<=1||paused)return;const timer=setInterval(()=>setActive(current=>(current+1)%items.length),Math.max(3,Number(interval)||6)*1000);return()=>clearInterval(timer)},[items.length,interval,paused])
  if(!items.length)return null
  const item=items[active]||items[0]
  const move=direction=>setActive(current=>(current+direction+items.length)%items.length)
  return <section className="testimonial-section open9-section-alt border-t border-white/8 px-5 py-24 lg:px-8" onMouseEnter={()=>setPaused(true)} onMouseLeave={()=>setPaused(false)} onFocusCapture={()=>setPaused(true)} onBlurCapture={()=>setPaused(false)}><div className="mx-auto max-w-7xl"><Open9SectionHead eyebrow="Testimonials" title={title} link={null}/><div className="testimonial-stage mt-12" aria-live="polite"><article key={`${item.name}-${active}`} className="testimonial-slide"><span className="testimonial-quote"><Quote size={30} fill="currentColor"/></span><blockquote>“{item.testimonial}”</blockquote><div className="testimonial-person">{item.photo_url?<img src={mediaUrl(item.photo_url)} alt={`Foto ${item.name}`}/>:<span className="testimonial-avatar-fallback">{item.name.slice(0,1).toUpperCase()}</span>}<span><b>{item.name}</b><small>{item.role}</small></span></div></article>{items.length>1&&<div className="testimonial-controls"><button type="button" onClick={()=>move(-1)} aria-label="Testimoni sebelumnya"><ChevronLeft size={20}/></button><div className="testimonial-dots" aria-label={`Testimoni ${active+1} dari ${items.length}`}>{items.map((testimonial,index)=><button type="button" key={`${testimonial.name}-${index}`} onClick={()=>setActive(index)} className={index===active?'active':''} aria-label={`Tampilkan testimoni ${index+1}`} aria-current={index===active?'true':undefined}/>)}</div><button type="button" onClick={()=>move(1)} aria-label="Testimoni berikutnya"><ChevronRight size={20}/></button></div>}</div></div></section>
}

