function hostCities(items){
  const cities=new Map()
  items.flatMap(item=>(item.sessions||[]).map(session=>({...session,competition_title:item.title}))).forEach(session=>{
    const key=session.city.trim().toLowerCase(),current=cities.get(key)
    if(!current)cities.set(key,{city:session.city,venue:session.venue,start:session.activity_start_date,end:session.activity_end_date,competitions:new Set([session.competition_title])})
    else{if(String(session.activity_start_date)<String(current.start))current.start=session.activity_start_date;if(String(session.activity_end_date)>String(current.end))current.end=session.activity_end_date;current.competitions.add(session.competition_title)}
  })
  return cities.size?[...cities.values()].sort((a,b)=>String(a.start).localeCompare(String(b.start))).map(city=>({...city,competition_count:city.competitions.size})):BSI_FLASH_CITY_FALLBACK
}

