  useEffect(()=>{api('/manage/competition-types').then(data=>{setItems(data);if(!value){const initial=data.find(item=>item.is_active&&item.category_group===legacyCategory)||data.find(item=>item.is_active);if(initial)onChange(initial)}}).catch(()=>setItems([]))},[])
