    {canEdit&&<section className="mb-6 rounded-3xl border border-violet-100 bg-violet-50 p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="font-display text-xl font-bold">Dokumen Unduhan Peserta</h2><p className="mt-1 text-sm text-slate-500">Pilih lomba untuk mengunggah template dan dokumen yang dapat diunduh peserta.</p></div></div><div className="mt-4 flex flex-wrap gap-2">{items.map(competition=><button key={competition.id} onClick={()=>setDownloadsModal(competition)} className="btn-ghost bg-white text-sm"><Download size={15}/>{competition.title} ({(competition.downloadable_documents||[]).length})</button>)}</div></section>}
    <div className="grid gap-4 lg:grid-cols-2">{items.map(x=><div key={x.id} className="flex gap-4 rounded-3xl bg-white p-4"><img className="h-32 w-24 rounded-2xl object-cover" src={x.poster_url}/><div className="min-w-0 flex-1"><div className="flex flex-wrap gap-2 text-xs font-bold"><span className="text-blue-600">{x.competition_type?.name||x.category}</span><span className="rounded-full bg-cyan-100 px-2 text-cyan-800">{x.participation_type==='team'?`Tim · ${x.team_size} orang`:'Individu'}</span></div><h3 className="mt-1 truncate font-display text-lg font-bold">{x.title}</h3><p className="mt-2 text-xs text-slate-500">{x.registrations_count} pendaftar</p><div className="mt-4 flex flex-wrap gap-2">{canEdit&&<button onClick={()=>setForm(x)} className="btn-ghost py-1.5 text-xs"><Pencil size={13}/>Edit Lomba</button>}<button onClick={()=>setGuideModal(x)} className="btn-ghost py-1.5 text-xs text-blue-700"><ClipboardCheck size={13}/>Panduan</button><button onClick={()=>setFormatModal(x)} className="btn-ghost py-1.5 text-xs"><Users size={13}/>Format</button>{canManage&&<button onClick={()=>remove(x.id)} className="btn-ghost py-1.5 text-xs text-rose-600"><Trash2 size={13}/></button>}</div></div></div>)}</div>
    {slotSetup&&<SlotSetupModal close={()=>setSlotSetup(false)} next={({slots,timelineCount})=>{setSlotSetup(false);setForm({...blankComp,pic_slots:slots,timeline:Array.from({length:timelineCount},()=>({label:'',type:'single',date:'',start_date:'',end_date:''}))})}}/>}
    {form&&<GlobalCityCompetitionForm item={form} close={()=>setForm(null)} saved={()=>{setForm(null);load()}}/>}
