  const toggleAccount=async account=>{try{await api(`/manage/accounts/${account.id}`,{method:'PUT',body:JSON.stringify({...account,password:'',competition_id:account.competition_id||account.competition?.id||null,is_active:!account.is_active})});loadAccounts()}catch(e){alert(e.message)}}
  const removeRole=async role=>{if(!confirm(`Hapus role ${role.name}?`))return;try{await api(`/manage/roles/${role.id}`,{method:'DELETE'});loadRoles()}catch(e){alert(e.message)}}
  const roleName=account=>account.role_name||({super_admin:'Super Admin',pic:'PIC Lomba',judge:'Juri',participant:'Peserta'}[account.role]||account.role)
