  const removeSlide=index=>setContent(current=>({...current,slides:current.slides.filter((_,i)=>i!==index)}))
  const moveSlide=(index,direction)=>setContent(current=>{const slides=[...current.slides],target=index+direction;if(target<0||target>=slides.length)return current;[slides[index],slides[target]]=[slides[target],slides[index]];return {...current,slides}})
  const submit=async event=>{event.preventDefault();setBusy(true);setError('');setSaved(false);const form=new FormData();for(const field of ['badge','title_primary','title_accent','description','primary_button_label','primary_button_url','secondary_button_label','secondary_button_url','hashtag','slide_interval'])form.set(field,content[field]);content.slides.forEach((slide,index)=>{form.set(`slides[${index}][image_url]`,slide.image_url||'');form.set(`slides[${index}][alt_text]`,slide.alt_text||'');if(slide._file)form.set(`slide_images[${index}]`,slide._file)});try{setContent(await api('/manage/content/home-hero',{method:'POST',body:form}));setSaved(true);setTimeout(()=>setSaved(false),2500)}catch(e){setError(e.errors?.general?.[0]||e.message)}finally{setBusy(false)}}
  if(!content)return error?<div className="rounded-2xl bg-rose-100 p-4 font-bold text-rose-700">{error}</div>:<Loader/>
